#include "REVENGE.h"

// 397F:000E: short FarStringCompare(const char far *left, const char far *right)
// Returns the unsigned-byte difference at the first mismatch, as Borland strcmp does.
short FarStringCompare(
	const char *left,
	const char *right)
{
	const char *rightScan = right;
	word16 remaining = 0xFFFF;
	word16 compareCount;
	byte leftCharacter = 0x00;
	byte rightCharacter = 0x00;

	while (remaining != 0x00)
	{
		byte character = (byte) *rightScan++;
		--remaining;
		if (character == 0x00)
			break;
	}
	compareCount = (word16) ~remaining;

	while (compareCount != 0x00)
	{
		leftCharacter = (byte) *left++;
		rightCharacter = (byte) *right++;
		--compareCount;
		if (leftCharacter != rightCharacter)
			break;
	}

	return (short) ((word16) leftCharacter - (word16) rightCharacter);
}
